window.EVENTS=[{"slug":"set-out-pathfinder","t":"Set Out, Pathfinder!","run":"","kind":"event","ends":"","starts":"","d":"Welcome to Idyll! Claim your starter rewards and begin your adventure!","rules":["1. During the event, log in to the game each day to complete that day’s check-in and earn rewards based on your cumulative check-in count.","2. The daily check-in count resets at 04:00 (UTC+0). Check in for a total of 7 days to claim all rewards."],"rw":[["2","Aniipod Ultra"],["1","Mystery Egg Box - REGEN"],["1","Capafruit"],["5","Tumbler"],["1","Ferocious Fang"],["1","Mystery Egg Box - Support"],["1","Sparkling Cube"],["1","Sparkling Cube"],["2","Aniipod Ultra"],["1","Capafruit"],["1","Ferocious Fang"],["1","Mystery Egg Box - Support"],["1","Mystery Egg Box - REGEN"],["5","Tumbler"],["100","Sparkling Crystal"],["50","Glimmer"],["1","Wonder Egg"],["50","Breezy Plains Dewdrop Crystal"],["100","Sparkling Crystal"],["100","Voxel Coin"],["100","Sparkling Crystal"],["100","Voxel Coin"],["100","Sparkling Crystal"],["100","Voxel Coin"]],"dates":[],"img":"img/events/set-out-pathfinder.webp"},{"slug":"journey-moments","t":"Journey Moments","run":"","kind":"event","ends":"3d 20h","starts":"","d":"Every encounter along the way is worth treasuring. Log in for the required number of days during the event to claim your travel gifts, and build your own collection of special moments with your Aniimo partners!","rules":["1. During the event, log in to the game each day to complete that day’s check-in and earn rewards based on your cumulative check-in count.","2. The daily check-in count resets at 04:00 (UTC+0). Check in for a total of 7 days to claim all rewards."],"rw":[["150","Sparkling Crystal"],["150","Sparkling Crystal"],["150","Sparkling Crystal"],["150","Sparkling Crystal"],["200","Sparkling Crystal"],["200","Sparkling Crystal"],["1","Sparkling Egg"],["1,000","Sparkling Crystal"],["1","Sparkling Egg"],["100","Sparkling Crystal"],["50","Glimmer"],["1","Wonder Egg"],["50","Breezy Plains Dewdrop Crystal"],["100","Sparkling Crystal"],["100","Voxel Coin"],["100","Sparkling Crystal"],["100","Voxel Coin"],["100","Sparkling Crystal"],["100","Voxel Coin"]],"dates":[],"img":"img/events/journey-moments.webp"},{"slug":"prismana-pact","t":"Prismana Pact","run":"","kind":"event","ends":"","starts":"","d":"Ten years ago, during the Bloom Festival’s Prismana Flow, the Institute was fortunate enough to preserve several Prismana Aniimo. With the Institute’s careful care, they’ve grown up to this day, waiting to meet the very best Pathfinder. Go choose one. It is destined to walk beside you on the journeys ahead.","rules":["1. During the event, Pathfinders can pick one Prismana Aniimo they like on the event screen. Once your title is promoted to Junior Wayfarer, you can claim the Aniimo you picked. You can change your selection at any time before claiming.","2. The Aniimo you claim will be in Prismana Form, with a randomly generated personality. After you claim it, Phase 2 Prismana Pact will unlock.","3. After Prismana Pact unlocks, Pathfinders can continue collecting Prismana Aniimo within the event’s designated scope. Each time you register a new Prismana Aniimo, it will increase the corresponding Prismana Index completion progress.","4. If the Prismana Aniimo you claimed in Phase 1 is within the Prismana Pact Index scope, it will also count toward your completion progress. Getting the same Prismana Aniimo more than once will not increase progress again.","5. When your Prismana Index completion reaches the required milestones, you can claim the corresponding stage rewards.","6. You can check your current Prismana Aniimo registrations through View Index on the event screen, and keep hunting for Prismana Aniimo you haven’t registered yet."],"rw":[["1","Sparkling Cube"],["1,000","Sparkling Crystal"]],"dates":[],"img":"img/events/prismana-pact.webp"},{"slug":"journey-handbook","t":"Journey Handbook","run":"","kind":"event","ends":"3d 20h","starts":"","d":"Record every day you travel alongside your Aniimo buddies. Once your total check-in days reach the required amount, you can claim rewards.","rules":["1. During the event, log in to the game each day to complete that day’s check-in and earn rewards based on your cumulative check-in days.","2. The daily check-in count resets at 04:00 (UTC+0). Check in for a total of 30 days to claim all rewards."],"rw":[["1","Lucky Cube Pack"],["1","Journey Appearance Pack"],["1","Big Pink Eyes Pack"],["1","Bold True Self"],["1","Piopiota Hood Pack"],["1","Free-Spirited"],["1","Emberpup Backpack Pack"],["1","Piopiota Hood Pack"],["1","Emberpup Backpack Pack"],["1","Bold True Self"],["1","Free-Spirited"],["1","Journey Appearance Pack"],["1","Big Pink Eyes Pack"],["1","Lucky Cube Pack"],["100","Sparkling Crystal"],["50","Glimmer"],["1","Wonder Egg"],["50","Breezy Plains Dewdrop Crystal"],["100","Sparkling Crystal"],["100","Voxel Coin"],["100","Sparkling Crystal"],["100","Voxel Coin"],["100","Sparkling Crystal"],["100","Voxel Coin"]],"dates":[],"img":"img/events/journey-handbook.webp"},{"slug":"set-off-together","t":"Set Off Together!","run":"","kind":"event","ends":"45d 17h","starts":"","d":"Unlock the event to immediately receive the Emberpup Set, then log in for a total of 3 days to claim all rewards. (Make a purchase of any amount to activate the event.)","rules":["Complete a top-up of any amount (including Monthly Pass, Companion Handbook Advanced Edition, and Collector’s Edition) to unlock the event. Once it’s unlocked, immediately receive the Emberpup Set, and claim all rewards by logging in for 3 cumulative days."],"rw":[["1","Nimble Sprouting"],["1","Cool Cuteness"],["2","Aniipod Ultra"],["2","Sparkling Egg"],["2","Aniipod Ultra"],["2","Sparkling Egg"],["1","Nimble Sprouting"],["1","Cool Cuteness"],["1","Cuteness Overload"],["1","Soft Paw Touch"],["1","Sprightly Charm"],["1","Nightshadow Smolder"],["1","Blazing Wilds Trail"],["1","Searing Cool Touch"],["1","Vital Strides"],["1","Awoo Ears"],["1","Adorably Floppy Ears"],["100","Sparkling Crystal"],["50","Glimmer"],["1","Wonder Egg"],["50","Breezy Plains Dewdrop Crystal"],["100","Sparkling Crystal"],["100","Voxel Coin"],["100","Sparkling Crystal"],["100","Voxel Coin"],["100","Sparkling Crystal"],["100","Voxel Coin"]],"dates":[],"img":"img/events/set-off-together.webp"},{"slug":"tracing-the-trail-the-shadow-of-legend","t":"Tracing the Trail: The Shadow of Legend","run":"","kind":"event","ends":"45d 19h","starts":"","d":"Look out! Mysterious Legendary Aniimo have appeared in many places, sending abnormal surges of Vein Energy rippling across the land. The Institute urgently calls on Pathfinders to gather clues and pinpoint the Legendary Aniimo!","rules":["Unusual signs of Legendary Aniimo have begun appearing everywhere. The Institute is recruiting Pathfinders to go investigate, and bring back valuable photos and complete the field notes. Event Details","1. During the event, the Institute will unlock multiple investigation areas over time.","2. Each area has different investigation objectives and environmental features. Dispatch suitable Aniimo to explore them.","3. After completing an investigation, you can obtain the corresponding area rewards and may also receive an extra Chance Encounter Gift. Investigation Rules","1. Each investigation requires at least 2 Aniimo. You must designate 1 as the Leader Aniimo before the investigation.","2. After the investigation is complete, you will receive base rewards according to the dispatched Aniimo. Dispatching Aniimo meeting the area preference conditions increases your reward rating.","3. Prismana Form and Sparkling Aniimo can sense the residual energy of Legendary Aniimo, which will help speed up the investigation. Chance Encounter Gifts When passing through an area with Legendary Aniimo, something special might appear from their energy. After completing an investigation, you also have a chance to receive 1 Chance Encounter Reward. One of the following rewards will be granted at random: - Random Leader Aniimo Potential +1 - Starcryst Essence x1 - Capaseed x5 - Vein Essence x1 ※ The \"Random Leader Aniimo Potential +1\" effect can only be obtained once in each Aniimo’s lifetime. ※ Aniimo with max Potential cannot obtain the \"Random Leader Aniimo Potential +1\" effect."],"rw":[["2","Psyche Fruit"],["125","Breezy Plains Dewdrop Crystal"]],"dates":[],"img":"img/events/tracing-the-trail-the-shadow-of-legend.webp"},{"slug":"glamour-star","t":"Glamour Star","run":"","kind":"event","ends":"4d 20h","starts":"","d":"The Glamour Star Auditions are open! Dress up your Aniimo according to the theme and aim for a high score to become the brightest star!","rules":["1. After the event begins, Polaris Institute will announce the theme for the Glamour Star Auditions.","2. Pathfinders can choose a suitable Aniimo and pair it with accessories based on the current theme to enter the event.","3. The Institute will score each Aniimo based on how well the Aniimo and its accessories match the theme.","4. Reach the required score milestones to claim the corresponding rewards.","5. Each Glamour Star event can be attempted multiple times, but each reward can only be claimed once."],"rw":[["100","Sparkling Crystal"],["100","Voxel Coin"]],"dates":[{"name":"Glamour Star Bonus Flower Party Grass Nova Stage Energetic 100","dates":"25 Sept – 1 Oct","status":"Ended"},{"name":"Glamour Star Bonus Water Carnival Swim Nova Stage Water 100","dates":"9 Oct – 15 Oct","status":"Ended"},{"name":"Glamour Star Bonus Sleepless Night Nighttime Form Lumin Stage Instinctive 100","dates":"23 Oct – 29 Oct","status":"Live"},{"name":"Glamour Star Bonus Water Carnival Swim Lumin Stage Water 100","dates":"6 Nov – 12 Nov","status":"Next"},{"name":"Glamour Star Bonus Stealth Hunt DPS Nova Stage Instinctive 100","dates":"20 Nov – 26 Nov","status":"Next"},{"name":"Glamour Star Bonus Winter Warmth Ice Nova Stage 100","dates":"4 Dec – 10 Dec","status":"Next"}],"img":"img/events/glamour-star.webp"},{"slug":"hatch-haste","t":"Hatch Haste","run":"","kind":"event","ends":"19h 56m","starts":"","d":"From Friday to Sunday, Aniimo egg hatching time is halved!","rules":["1. During the event, Egg hatch time is halved.","2. This only applies to Hatchinators in the Outpost, Astra, and Home.","3. When the event begins, the remaining hatch time of Eggs already hatching will be halved.","4. When the event ends, the remaining hatch time of Eggs that have already received the event speedup will not be affected.","5. During the event, if you have the Monthly Pass, the event bonus is applied first when hatching begins, then the Monthly Pass benefits are applied."],"rw":[],"dates":[],"img":"img/events/hatch-haste.webp"},{"slug":"sparkelf-aniimo","t":"SPARKELF × Aniimo","run":"","kind":"event","ends":"45d 19h","starts":"","d":"Drawn by the bond between humans and Aniimo, Sparkelf has arrived in Astra from SylphIsle! Keep your Sparks going with friends and make progress in the codex to complete quests, collect Sparks, and exchange them for awesome rewards!","rules":["1. During the event, you can get Sparks through the following ways: · Complete the Fire Companion Codex quest. · Take part in the Continuing Sparks mode. · Check in at the Sparkelf statue in Horizon Square (only once per day).","2. Continuing Sparks mode details: · Each day, interact with friends to light up Sparks. Interactions include: ※ Chat: send messages to each other. ※ Party Up: form a team. ※ Gift: send gifts to each other. ※ Aniimo Exchange: exchange Aniimo. ※ Visit Home: visit each other. · After you light up a Spark, a Spark icon will appear next to your friend’s nickname. The number next to it shows how many days you and that friend have interacted during the event. Once you hit 5 days or more, the Spark icon will also level up. · The Spark icon will gray out after the daily server refresh at 04:00. Interact with your friends to light it up again.","3. Event rewards: · When your personal total number of Sparks reaches the required amount, you can claim personal progress rewards. · When the server-wide total number of Sparks reaches the required amount, all players can claim server-wide progress rewards. · Special Notes: ※ The Sparkelf with the Sparkling Mutation (including the Basic Form and Prismana Form) has a sparkling outline effect, but no partial recolor effect. ※ The Sparkelf (Prismana Form) will be unavailable after the event ends. Please stay tuned for future official announcements."],"rw":[["1","Prismana Sparkelf Egg"],["50","Breezy Plains Dewdrop Crystal"],["5","Blaze Stone"],["4","Bouncing Sparkelf"],["4","Prismatic Flame"],["4","Here comes the Sparkelf!"],["4","Sparkelf"],["4","Formula - Fire Sprout Biscuit"]],"dates":[],"img":"img/events/sparkelf-aniimo.webp"},{"slug":"boundless-twining","t":"Boundless Twining","run":"","kind":"event","ends":"","starts":"","d":"Wherever you are, your bond with your Aniimo never breaks. Log in with the same account on both mobile and PC/console during the event to claim lots of rewards!","rules":["1. During the event, log in with the same game account separately on mobile and PC/console to complete the Cross-Platform Play quest.","2. Both mobile and PC/console logins must use a sign-in method linked to the same account. Logging in with different accounts will not count toward event progress.","3. Once you’ve completed the cross-platform login, you can claim the corresponding Cross-Platform Play reward on the event page.","4. Each game account can complete the Cross-Platform Play quest and claim its reward only once."],"rw":[["260","Glimmer"],["50","Sparkling Crystal"],["10","Growth Flower"]],"dates":[],"img":"img/events/boundless-twining.webp"},{"slug":"harvest-moon-festival","t":"Harvest Moon Festival","run":"","kind":"event","ends":"2d 19h","starts":"","d":"The light of the full moon spills across the land as the wind carries the scent of ripened crops far and wide. Drawn by the fragrance, people follow the moonlit path to celebrate the harvest together.","rules":[],"rw":[],"dates":[{"name":"Stage","dates":"15 Sept – 6 Oct","status":"Ended"},{"name":"Stage","dates":"6 Oct – 20 Oct","status":"Ended"},{"name":"Stage","dates":"20 Oct – 28 Oct","status":"Live"}],"img":"img/events/harvest-moon-festival.webp"},{"slug":"quick-leveling-guide","t":"Quick Leveling Guide","run":"","kind":"gameplay","ends":"","starts":"","d":"","rules":["The Polaris Institute has put together a handy guide to earning Safaris efficiently while exploring Idyll, to help Pathfinders grow faster. Check it out now!"],"rw":[],"dates":[],"img":""},{"slug":"legendary-journey-departure-with-the-wind","t":"Legendary Journey: Departure with the Wind","run":"","kind":"gameplay","ends":"45d 17h","starts":"","d":"A powerful Legendary Aniimo has been born, drawing Vein energy together and forming a strange energy rift. Yet the Vein is surging abnormally, and the affected Legendary Aniimo has become ferocious. Pathfinder, please explore the energy rift at once. With courage and a healing heart, soothe the out-of-control Aniimo and put an end to this disturbance.","rules":[],"rw":[["500","Glimmer"]],"dates":[],"img":""},{"slug":"vein-abundance","t":"Vein Abundance: Prismana Carnival","run":"","kind":"gameplay","ends":"20h 7m","starts":"","d":"The Vein energy in Breezy Plains is surging like never before! All four season-exclusive Prismana Aniimo will appear at the same time in their respective areas. Join the Prismana Carnival!","rules":["1. According to observations by the Institute, Vein energy has been unusually active in some regions recently, causing unusual changes in the local ecosystem.","2. During the event, the chance of Nova Stage Aniimo appearing will be greatly increased for the first 3 Nurture sessions conducted in the designated area each weekend. After Veinfruit is harvested, the amount of Prismatic Energy gained in the area will receive an additional 50% boost. Completing Nurture increases the current area’s Prismatic Energy. Capturing Aniimo also has a chance to trigger a Lucky Strike, increasing the area’s Prismatic Energy. · Each time Nurture increases the area’s Prismatic Energy, there is a 3% chance of triggering a Prismana Flow, causing local Prismana Aniimo to appear. · Each time a Lucky Strike triggered while capturing an Aniimo increases the area’s Prismatic Energy, there is a 0.6% chance of triggering a Prismana Flow, causing local Prismana Aniimo to appear.","3. Every weekend, abundant Vein energy will also draw large numbers of Aniimo to gather in the designated area. Pathfinders can head there to explore and capture them.","4. During the event, some special Prismana Aniimo will also be drawn by Vein energy and appear in designated areas for a limited time. See the event schedule below for the Prismana Aniimo appearing in each phase and their corresponding areas.","5. Prismana Aniimo Spawn Schedule: Sept. 21, 2026 04:00–Sept. 28, 2026 03:59 (UTC+0) Prismana Glynsera appears in Beast Fang Ridge. Sept. 28, 2026 04:00–Oct. 5, 2026 03:59 (UTC+0) Prismana Melloblum appears in Rosetower Woods. Oct. 5, 2026 04:00–Oct. 12, 2026 03:59 (UTC+0) Prismana Waleetle appears in Berylline Vale. Oct. 12, 2026 04:00–Oct. 19, 2026 03:59 (UTC+0) Prismana Inferlupa appears in Nimbus Fields. Oct. 19, 2026 04:00–Oct. 26, 2026 03:59 (UTC+0) Prismana Glynsera, Prismana Melloblum, Prismana Waleetle, and Prismana Inferlupa will appear simultaneously in Beast Fang Ridge, Rosetower Woods, Berylline Vale, and Nimbus Fields, respectively."],"rw":[],"dates":[{"name":"Vein Abundance: Forest of Falling Stars Prismana Stellarys","dates":"18 Sept – 20 Sept","status":"Ended"},{"name":"Vein Abundance: Beast Fang Ridge Prismana Glynsera","dates":"21 Sept – 27 Sept","status":"Ended"},{"name":"Vein Abundance: Rosetower Woods Prismana Melloblum","dates":"28 Sept – 4 Oct","status":"Ended"},{"name":"Vein Abundance: Berylline Causeway Prismana Waleetle","dates":"5 Oct – 11 Oct","status":"Ended"},{"name":"Vein Abundance: Nimbus Fields Prismana Inferlupa","dates":"12 Oct – 18 Oct","status":"Ended"},{"name":"Vein Abundance: Prismana Carnival Prismana Glynsera Melloblum Waleetle Inferlupa","dates":"19 Oct – 25 Oct","status":"Live"}],"img":"img/events/vein-abundance.webp"},{"slug":"star-crossed-tea-party","t":"Star-Crossed Tea Party","run":"","kind":"gameplay","ends":"18h 17m","starts":"","d":"Now that the busy adventure has come to a pause, why not rest beneath the starlight with your Aniimo?","rules":["1. Every day from 18:00 to 2:00 (UTC+0) the next day, the cafe in Astra hosts the Star-Crossed Tea Party. After a long day on your journey, why not stop by and relax? Chat with passing travelers, share stories from today’s adventure, and you might even meet a new ally along the way.","2. Stay and interact during the tea party to earn Voxel Coins and Season Stamps. Daily Limits: Voxel Coin ×150 Season Stamp ×40"],"rw":[["100","Sparkling Crystal"],["50","Glimmer"],["1","Wonder Egg"],["50","Breezy Plains Dewdrop Crystal"],["100","Sparkling Crystal"],["100","Voxel Coin"],["100","Sparkling Crystal"],["100","Voxel Coin"],["100","Sparkling Crystal"],["100","Voxel Coin"]],"dates":[],"img":""},{"slug":"holo-battle-sim","t":"Holo-Battle Sim","run":"","kind":"gameplay","ends":"","starts":"","d":"Join the Holo-Battle Sim and boost your combat strength! Complete training challenges to claim rewards!","rules":["1. \"Holo-Battle Sim\" is a solo challenge developed by the Battle Art Department for students. It uses holographic simulations based on documented Aniimo of various kinds, together with training robots.","2. Each element’s Holo-Battle Sim is divided into 4 difficulties. Each difficulty offers \"First Clear Rewards\" and \"Training Incentives\".","3. \"First Clear Rewards\" can only be claimed once per season, upon clearing the corresponding difficulty. \"Training Incentives\" refresh weekly. Clearing the highest difficulty lets you claim the \"Training Incentives\" for all lower difficulties as well."],"rw":[["6","Starcryst Essence"],["12","Aniipod Ultra Voucher"],["3","Tumbler"],["9","Star Sand"],["18","Star Dust"],["60","Aniipod Mega"]],"dates":[],"img":""},{"slug":"operation-egg-heist","t":"Operation: Egg Heist","run":"","kind":"gameplay","ends":"","starts":"","d":"Head to the Lost Isles, search for rare Eggs, and evacuate with them successfully!","rules":["1. Head to the Lost Isles, search the ruins for rare Eggs, and evacuate by boat!"],"rw":[],"dates":[],"img":""},{"slug":"holo-battle-interlink","t":"Holo-Battle Interlink","run":"","kind":"gameplay","ends":"20h 35m","starts":"","d":"Team up in a four-player squad, take on powerful Aniimo in a holographic simulation, earn rewards, and climb the leaderboard!","rules":["1. Holo-Battle Interlink is a four-person team challenge designed by the Battle Art Department. Using the data from the most powerful Aniimo ever as a blueprint, the challenge employs holographic simulation technology to create scenarios for trainees. Teams that complete the challenge will receive rewards and be ranked based on their performance rating.","2. The system records the highest star rank achieved during the current period, unlocks the corresponding rewards based on that best star rank, and grants those rewards upon settlement when you exit the mode."],"rw":[["200","Sparkling Crystal"],["2","Starcryst Essence"],["1","Wonder Egg"],["2","Advanced Held Item Core"],["2","Tumbler"]],"dates":[],"img":"img/events/holo-battle-interlink.webp"},{"slug":"mysterious-vendor","t":"Mysterious Vendor","run":"","kind":"gameplay","ends":"","starts":"","d":"The Mysterious Vendor has new stock every day! Come see what great deals are waiting for you!","rules":["1. The Mysterious Vendor restocks daily at 04:00 AM (UTC+0), so don’t forget to stop by!"],"rw":[["100","Giant Rubber Duck"],["100","Sparkling Crystal"],["50","Glimmer"],["1","Wonder Egg"],["50","Breezy Plains Dewdrop Crystal"],["100","Sparkling Crystal"],["100","Voxel Coin"],["100","Sparkling Crystal"],["100","Voxel Coin"],["100","Sparkling Crystal"],["100","Voxel Coin"]],"dates":[],"img":""},{"slug":"test-rewards-refunded","t":"Test Rewards Refunded","run":"","kind":"gameplay","ends":"140d 20h","starts":"","d":"Thanks for your support during the test! Test rewards are now ready to claim. Head to the event screen to claim your corresponding refunded rewards.","rules":["1. Refunded test rewards can only be claimed by test accounts that meet eligibility requirements.","2. Log in to the event screen with the corresponding account to claim your rewards.","3. After claiming, check your corresponding character to receive them.","4. For more info, view the rules on the event screen."],"rw":[],"dates":[],"img":""},{"slug":"polaris-liaison-station","t":"Polaris Liaison Station","run":"","kind":"gameplay","ends":"","starts":"","d":"","rules":["1. During the event, visit the \"Polaris Liaison Station\" and follow the instructions on the event page to link the specified account or platform.","2. Available linking options may vary by region. Please refer to the event page for your region to see which accounts and platforms are currently supported.","3. Your linking quest is considered complete once the account is successfully linked and verified. Make sure the account information you provide is correct to avoid issues with future login or account access.","4. Once the account is successfully linked, the corresponding rewards will be sent via in-game mail. Be sure to check your mailbox.","5. Quest completion status and available rewards are based on what is shown on the event page. If you have completed the linking process but haven’t received your rewards, try logging into the game again or contact official Support.","6. Event times, supported platforms, and rewards may vary by region or platform. Please refer to the in-game information for details."],"rw":[],"dates":[],"img":""},{"slug":"official-community","t":"Official Community","run":"","kind":"gameplay","ends":"","starts":"","d":"Receive a reward for each official community account you follow!","rules":["1. During the event, Pathfinders can claim the corresponding reward for each official community they follow!","2. Each follow reward can only be claimed once per official community."],"rw":[],"dates":[],"img":""},{"slug":"whos-that-aniimo","t":"Who’s That Aniimo?","run":"","kind":"upcoming","ends":"","starts":"4d 19h","d":"Study the silhouette, gather the clues, and guess the mystery Aniimo!","rules":["1. Once the event begins, Polaris Institute will reveal this period’s mystery Aniimo silhouette.","2. The initial silhouette will only show the mystery Aniimo’s distinctive features, with the remaining parts hidden. Pathfinders can reveal the hidden parts by photographing Aniimo that share the same features as the mystery Aniimo.","3. Photograph an Aniimo matching the silhouette’s corresponding form and submit it to complete the research topic and claim the corresponding rewards. Successfully photographing before the full silhouette is revealed earns you bonus Aniimo Observation Rewards!","4. Pathfinders can also select photos from their existing album that meet the topic requirements for submission. If a photo contains this period’s mystery Aniimo, it counts toward event completion too.","5. Pay attention to Aniimo forms — only photos where the submitted Aniimo matches the mystery Aniimo’s exact form will count toward event completion.","6. Pathfinders can complete the event by photographing their own Aniimo, other players’ Aniimo, or wild Aniimo on the continent of Idyll.","7. Aniimo in the Holo-Battle Sim are holographic projections, and Aniimo found in Sanctums are bound by ancient seals. Photos taken in these two locations cannot be recognized or submitted."],"rw":[["100","Sparkling Crystal"],["50","Glimmer"],["1","Wonder Egg"],["50","Breezy Plains Dewdrop Crystal"],["1","Tumbler"]],"dates":[{"name":"Who’s That Aniimo? Answer Budclaw Basic Form 100 50 1","dates":"16 Sept – 24 Sept","status":"Ended"},{"name":"Who’s That Aniimo? Answer Glacy Flowerfield Form 100 50 1","dates":"2 Oct – 8 Oct","status":"Ended"},{"name":"Who’s That Aniimo? Answer Inferlupa Prismana Form 100 50 1","dates":"16 Oct – 22 Oct","status":"Ended"},{"name":"Who’s That Aniimo? 100 50 1","dates":"30 Oct – 5 Nov","status":"Next"}],"img":"img/events/whos-that-aniimo.webp"},{"slug":"idyll-ecology-field-notes","t":"Idyll Ecology Field Notes","run":"","kind":"ended","ends":"","starts":"","d":"The Institute has discovered that some Aniimo are affected by the Mountain Forest and can take on unique forms. Head out and investigate the designated Aniimo to help the Institute record their ecological changes!","rules":["1. During the event, Polaris Institute will publish an Ecological Investigation. Each investigation focuses on a single ecological theme and selects a range of representative Aniimo as investigation targets.","2. Pathfinders must follow the investigation list and catch the corresponding Aniimo to help the Institute complete its ecological investigation and earn Investigation Points.","3. Each target Aniimo only grants points the first time its investigation is completed. Catching the same target again will not grant additional points.","4. Please pay close attention to Aniimo forms. Only catching an Aniimo in the same form as listed on the investigation list will complete the corresponding investigation.","5. Once your accumulated Investigation Points reach the specified requirements, you can claim the corresponding milestone rewards.","6. If the investigation target is an Aniimo the Pathfinder has not yet registered in the Aniilog, the points earned for completing its investigation for the first time will be doubled."],"rw":[["100","Sparkling Crystal"],["25","Aniipod Track"],["100,000","Credits"]],"dates":[{"name":"Idyll Ecological Investigation Investigate Budclaw Bay Form Iris Grassland Form Chirpi Basic Form Flameruff Basic Form 20 5 20K","dates":"16 Sept – 16 Sept","status":"Ended"},{"name":"Idyll Ecology Field Notes Investigate Chirpi Beach Form Iris Forest Form Hummin Mountain Form Bolty Basic Form 20 5 20K","dates":"17 Sept – 17 Sept","status":"Ended"},{"name":"Idyll Ecology Field Notes Investigate Budsquire Bonesky Popota Shelly Basic Form 20 5 20K","dates":"18 Sept – 18 Sept","status":"Ended"},{"name":"Idyll Ecology Field Notes Investigate Jawling Basic Form Helmut Basic Form Emberpup Highland Form Cornet Basic Form 20 5 20K","dates":"19 Sept – 19 Sept","status":"Ended"},{"name":"Idyll Ecology Field Notes Investigate Susuta Flutternym Popota Bonesky Nighttime Form 20 5 20K","dates":"20 Sept – 20 Sept","status":"Ended"},{"name":"Idyll Ecology Field Notes Investigate Flutternym Pomegg Sparki Pranky Flowerfield Form 100 25 100K","dates":"2 Oct – 8 Oct","status":"Ended"},{"name":"Idyll Ecology Field Notes Investigate Flameruff Timberline Form Bolty Timberline Form Hexxin Mountain Form Flutternym Timberline Form 100 25 100K","dates":"16 Oct – 22 Oct","status":"Ended"}],"img":"img/events/idyll-ecology-field-notes.webp"},{"slug":"aniimo-discovery","t":"Aniimo Discovery","run":"","kind":"ended","ends":"","starts":"","d":"The Institute has discovered a brand-new Aniimo in Idyll! Go track it down!","rules":["1. The Polaris Institute has discovered a brand-new Aniimo in Idyll and hopes Pathfinders will assist with its investigation and research.","2. Pathfinders can spend search attempts to track the Aniimo across Idyll and catch it.","3. The Institute will periodically replenish free search attempts for Pathfinders to support ongoing exploration. Unused free search attempts cannot be accumulated, so please remember to use them in time.","4. If you currently have no free search attempts remaining, you can spend Vein Essence and search attempts to continue searching.","5. Pathfinders can complete investigation quests related to this Aniimo to earn generous rewards.","6. Based on your investigation quest progress, you can unlock different search bonuses in the Research Center."],"rw":[["100","Sparkling Crystal"],["2","Psyche Fruit"],["1","Thunder Soul"],["1","Perfect Dazmand Egg"],["200","Breezy Plains Dewdrop Crystal"],["65","Growth Fruit"],["12","Tumbler"],["3","Flux Crystal"]],"dates":[],"img":"img/events/aniimo-discovery.webp"},{"slug":"taptap-exclusive-event","t":"TapTap Exclusive Event","run":"","kind":"ended","ends":"","starts":"","d":"Various events are underway. Win reward packs, merchandise and premium physical prizes!","rules":["1. Various TapTap events are underway. Win reward packs, merchandise and premium physical prizes!"],"rw":[],"dates":[],"img":""}];
