window.PSKILLS=[{"n":"Heal","k":"active","mx":1,"d":"You sprinkle healing dust on the engaged Aniimo to restore its HP.","lv":[["I Student",1]],"th":"รักษา","dth":"คุณโปรยผงรักษาใส่แอนีโมที่กำลังต่อสู้อยู่เพื่อฟื้นฟู HP ของมัน"},{"n":"Aeroboard","k":"active","mx":1,"d":"A hover board that helps you travel faster and does not cost stamina. Can also be used in Astra.","lv":[["I Student",1]],"th":"แอโรบอร์ด","dth":"โฮเวอร์บอร์ดช่วยให้คุณเดินทางเร็วขึ้น โดยไม่เสียค่าสตามินา ใช้งานได้ในแอสตร้า"},{"n":"Enhanced Twining","k":"passive","mx":5,"d":"Increases Aniimo damage by 7/10/15/20/25% after twining.","lv":[["I Student",1],["II Student",2],["I Wayfarer",2],["III Wayfarer",3],["I Trailblazer",3]],"th":"ผูกจิตขั้นสูง","dth":"แอนีโมสร้างดาเมจเพิ่ม 25% หลังจากผูกจิต"},{"n":"Elemental Boost","k":"passive","mx":4,"d":"Increases Elemental Counters effect by 2/4/7/10%.","lv":[["I Student",1],["III Student",2],["II Wayfarer",3],["I Trailblazer",3]],"th":"บูสต์ธาตุ","dth":"เพิ่มเอฟเฟกซ์การต้านธาตุ 10%"},{"n":"Master Trainer","k":"passive","mx":4,"d":"Aniimo EXP gained from catching and defeating targets or using EXP items increases by 10/15/20/30%.","lv":[["I Student",1],["III Student",2],["II Wayfarer",3],["I Trailblazer",3]],"th":"ผู้ฝึกสอนระดับปรมาจารย์","dth":"EXP ของแอนีโมที่ได้รับจากการจับและการกำจัดเป้าหมาย หรือการใช้ไอเทม EXP เพิ่มขึ้น 30%"},{"n":"Mode Switch","k":"passive","mx":1,"d":"Enables switching between Catch Mode, Attack Mode, and Defense Mode.","lv":[["I Student",1]],"th":"การสลับโหมด","dth":"เปิดใช้งานการสลับระหว่างโหมดจับ โหมดโจมตี และโหมดป้องกัน"},{"n":"Pro Catcher","k":"passive","mx":1,"d":"Unlocks Aniipod Pro in the shop.","lv":[["I Student",1]],"th":"นักจับมือโปร","dth":"ปลดล็อกแอนีพ็อด โปรในร้านค้า"},{"n":"Gravity Pull","k":"active","mx":1,"d":"Activates the target’s energy field to create a gravity link, allowing you to move objects with ancient energy patterns from a distance. Essential for solving puzzles in ancient ruins.","lv":[["II Student",1]],"th":"ศูนย์รวมโน้มถ่วง","dth":"เปิดใช้งานสนามพลังงานของเป้าหมาย เพื่อสร้างการเหนี่ยวนำแรงโน้มถ่วง ทำให้คุณสามารถเคลื่อนย้ายวัตถุที่มีลวดลายพลังงานโบราณจากระยะไกล จำเป็นสำหรับการแก้ปริศนาในซากโบราณ"},{"n":"Mega Mallet","k":"active","mx":1,"d":"Smashes the targets within a circular area in front with a huge energy hammer, dealing a large amount of BREAK damage. It can also smash solid objects.","lv":[["II Student",1]],"th":"ค้อนใหญ่ยักษ์","dth":"ใช้ค้อนพลังงานขนาดใหญ่ฟาดเป้าหมายในพื้นที่วงกลมด้านหน้า สร้างดาเมจทำลาย จำนวนมาก และสามารถทลายวัตถุแข็งได้"},{"n":"Boss Breaker","k":"passive","mx":1,"d":"Increases damage to Alpha and Omega by 5%.","lv":[["II Student",2]],"th":"จับโจรต้องจับหัวหน้าก่อน","dth":"เพิ่มความเสียหายต่อ อัลฟา และ โอเมก้า ขึ้น 5%"},{"n":"Dreamsong","k":"passive","mx":1,"d":"Unlocks Dreaple’s exceptional evolution.","lv":[["II Student",2]],"th":"เพลงบรรเลงฝัน","dth":"ปลดล็อกวิวัฒนาการพิเศษของแกะแดนฝัน"},{"n":"Tweetin’ Target","k":"active","mx":1,"d":"Consumes 1 Rubber Duck and throws it at the target area to draw the attention of all Aniimo in a non-combat state within range for 10s.","lv":[["III Student",1]],"th":"ร้องเรียกเป้าหมาย","dth":"ใช้เป็ดยาง 1 ตัว แล้วขว้างไปยังพื้นที่เป้าหมาย เพื่อดึงดูดความสนใจของแอนีโมทั้งหมดที่อยู่นอกการต่อสู้ภายในระยะ เป็นเวลา 10 วินาที"},{"n":"Plushie Pummel","k":"active","mx":1,"d":"You spin around and wave the doll like crazy, dealing BREAK damage to targets in your path and smashing hard objects.","lv":[["III Student",1]],"th":"หมัดตุ๊กตาปุกปุย","dth":"คุณหมุนตัวพร้อมกับแกว่งตุ๊กตาสุดแรง สร้างความเสียหายทำลายกับเป้าหมายในเส้นทางและทลายวัตถุแข็งได้"},{"n":"Quick Twine","k":"passive","mx":1,"d":"Amplifies your mind power and reduces the time needed to twine with an Aniimo to a mere instant.","lv":[["III Student",2]],"th":"ผูกจิตชั่วพริบตา","dth":"เสริมพลังจิตของคุณ และทำให้ผูกจิตกับแอนีโมได้ในชั่วพริบตา"},{"n":"Elemental Ward","k":"passive","mx":4,"d":"Increases Element Resistance effect by 2/4/7/10%.","lv":[["III Student",2],["I Wayfarer",2],["II Wayfarer",3],["I Trailblazer",3]],"th":"เกราะธาตุ","dth":"เพิ่มเอฟเฟกต์ต้านทานธาตุ 10%"},{"n":"Magic Horn","k":"passive","mx":1,"d":"Unlocks Tromber’s exceptional evolution.","lv":[["III Student",2]],"th":"แตรวิเศษ","dth":"ปลดล็อกวิวัฒนาการพิเศษของจิ๊บแตรยาว"},{"n":"Master Catcher","k":"passive","mx":1,"d":"Unlocks purchasing Aniipod Megas, Aniipod Hypers, Aniipod Traces, and Tumblers from shops.","lv":[["III Student",2]],"th":"ปรมาจารย์นักสะสม","dth":"ปลดล็อกการซื้อแอนีพ็อด เมก้า แอนีพ็อด ไฮเปอร์ แอนีพ็อด เทรซ และบอลดักจับจากร้านค้า"},{"n":"Revive","k":"active","mx":1,"d":"Allows you to revive Aniimo in your party.","lv":[["I Wayfarer",2]],"th":"คืนชีพ","dth":"ช่วยให้คุณคืนชีพแอนีโมในปาร์ตี้ได้"},{"n":"Research Expert","k":"passive","mx":4,"d":"Reporting grants 10/15/20/30% more Credits.","lv":[["I Wayfarer",2],["II Wayfarer",3],["III Wayfarer",3],["I Trailblazer",3]],"th":"นักวิจัยอาวุโส","dth":"ได้รับเครดิตจากการรายงานเพิ่มขึ้น 30%"},{"n":"Bubble Gun","k":"active","mx":1,"d":"Prevents the target Aniimo from Fainting. While the effect is active, its HP cannot drop below 1, allowing the Aniimo to be caught multiple times in battle.","lv":[["II Wayfarer",3]],"th":"ปืนฟอง","dth":"ป้องกันไม่ให้แอนีโมเป้าหมายหมดสติ ขณะเอฟเฟกต์ทำงาน HP จะไม่ลดต่ำกว่า 1 ทำให้สามารถจับแอนีโมตัวนั้นซ้ำได้หลายครั้งระหว่างการต่อสู้"},{"n":"Nimble Dodge","k":"passive","mx":1,"d":"Reduces stamina cost for dodging by 10%.","lv":[["II Wayfarer",3]],"th":"หลบหลีกคล่องแคล่ว","dth":"การหลบหลีกใช้สตามินาน้อยลง"},{"n":"Peculiar Rock Ball","k":"passive","mx":1,"d":"Unlocks Bouldus’s exceptional evolution.","lv":[["II Wayfarer",3]],"th":"ลูกหินประหลาด","dth":"ปลดล็อกวิวัฒนาการพิเศษของแมลงหินกลม"},{"n":"Go, Rubber Duck!","k":"active","mx":1,"d":"Consumes 1 Giant Rubber Duck and throws it at the target area, drawing the attention of all out-of-combat Aniimo within a large area for 20s.","lv":[["III Wayfarer",2]],"th":"ไปเลย! เป็ดยาง!","dth":"ใช้เป็ดยางตัวใหญ่ 1 ตัว แล้วขว้างไปยังพื้นที่เป้าหมาย เพื่อดึงดูดความสนใจของแอนีโมที่อยู่นอกการต่อสู้ทั้งหมดในพื้นที่ขนาดใหญ่เป็นเวลา 20 วิ."},{"n":"Measured Strike","k":"passive","mx":1,"d":"Aniimo deals 10% increased damage to targets in Break State.","lv":[["III Wayfarer",3]],"th":"","dth":""},{"n":"Sure Shot","k":"passive","mx":1,"d":"Greatly increases Aniipod’s targeting range.","lv":[["III Wayfarer",3]],"th":"ยิงแม่นยำ","dth":"เพิ่มระยะการโจมตีเป้าหมายของแอนีพ็อดอย่างมาก"},{"n":"Fast Charge","k":"passive","mx":1,"d":"Increases the charging speed of Aniimo ultimates by 10%.","lv":[["I Trailblazer",3]],"th":"ชาร์จด่วน","dth":"เพิ่มความเร็วในการชาร์จอัลติเมทของแอนีโม 10%"},{"n":"Unwavering Rampart","k":"passive","mx":1,"d":"Unlocks Rookey’s exceptional evolution.","lv":[["I Trailblazer",3]],"th":"ปราการไร้สั่นคลอน","dth":"ปลดล็อกวิวัฒนาการพิเศษของอัศวินน้องใหม่"}];
